package cn.balltv.portal;
import org.junit.*;import static org.junit.Assert.*;import java.util.*;import org.json.*;
public class HomeAdmissionTest {
 final long now=Events.epoch("2026-11-10 12:00");
 Feeds.Match match(String state,String time)throws Exception{Feeds.Match m=new Feeds.Match();m.source="74体育/球吧";m.id="1";m.home="甲";m.away="乙";m.title="甲 vs 乙";m.sport="2";m.room="1";m.status="live";m.eventState=state;m.time=time;m.raw=new JSONObject();return m;}
 @Before public void clear(){LiveState.ENDED.clear();LiveCatalog.ROWS.clear();LiveCatalog.SEEN.clear();StreamHealth.GOOD.clear();StreamHealth.BAD.clear();}
 @Test public void probeFailureDoesNotRemoveOtherwiseCurrentMatch()throws Exception{Feeds.Match m=match("live","2026-11-10 11:00");StreamHealth.fail(m,new Feeds.Line("hd","1",""),now);assertNull(StreamHealth.good(m,now));assertEquals(Arrays.asList(m),LiveState.admit(Arrays.asList(m),now));}
 @Test public void healthExpiryDoesNotMakeLiveMatchDisappear()throws Exception{Feeds.Match m=match("live","2026-11-10 11:00");StreamHealth.playing(m,new Feeds.Line("hd","1",""),"https://example.org/live.m3u8",now-180001);assertNull(StreamHealth.good(m,now));assertEquals(1,LiveState.admit(Arrays.asList(m),now).size());}
 @Test public void unknownStatusWithCurrentFixtureAndRoomIsVisibleAsChecking()throws Exception{Feeds.Match m=match("","2026-11-10 11:00");assertEquals(1,LiveState.admit(Arrays.asList(m),now).size());assertEquals("checking",m.status);assertEquals(LiveState.Phase.CHECKING,LiveState.phase(new Events.Group(m),now));}
 @Test public void twoHourPreparationRoomRemainsVisibleDespiteFailedProbe()throws Exception{Feeds.Match m=match("upcoming","2026-11-10 14:00");StreamHealth.fail(m,new Feeds.Line("hd","1",""),now);assertEquals(1,LiveState.admit(Arrays.asList(m),now).size());assertEquals("upcoming",m.status);assertEquals(LiveState.Phase.SOON,LiveState.phase(m,Arrays.asList(m),now));m.time="2026-11-10 14:01";assertEquals(LiveState.Phase.HIDE,LiveState.phase(m,Arrays.asList(m),now));}
 @Test public void delayedPreparationDoesNotDisappearTwentyMinutesAfterPlannedStart()throws Exception{Feeds.Match m=match("upcoming","2026-11-10 11:15");assertEquals(LiveState.Phase.SOON,LiveState.phase(m,Arrays.asList(m),now));}
 @Test public void endedExpiredAndAnonymousRoomsStillDoNotEnterHome()throws Exception{Feeds.Match ended=match("finished","2026-11-10 11:00"),old=match("live","2026-11-10 06:00"),anonymous=match("live","2026-11-10 11:00");anonymous.home="";assertTrue(LiveState.admit(Arrays.asList(ended,old,anonymous),now).isEmpty());}
 @Test public void scheduleDiscoveryIsAvailableWithoutRevisitingSchedule()throws Exception{Feeds.Match m=match("live","2026-11-10 11:00");LiveCatalog.remember(Arrays.asList(m),now);assertEquals(Arrays.asList(m),LiveCatalog.recent(now+60000));}
 @Test public void scheduleDiscoveryExpiresAndFinishedUpdateReplacesOldRoom()throws Exception{Feeds.Match m=match("live","2026-11-10 11:00");LiveCatalog.remember(Arrays.asList(m),now);assertTrue(LiveCatalog.recent(now+600001).isEmpty());LiveCatalog.remember(Arrays.asList(m),now);Feeds.Match ended=match("finished","2026-11-10 11:00");LiveCatalog.remember(Arrays.asList(ended),now+1);assertTrue(LiveCatalog.recent(now+2).isEmpty());}
 @Test public void refreshNeedsNoSeparateControlToRediscoverFixture()throws Exception{Feeds.Match m=match("live","2026-11-10 11:00");assertTrue(LiveCatalog.supplements(m.source));assertTrue(LiveCatalog.supplements("咖啡"));assertTrue(LiveCatalog.supplements("豆包"));assertTrue(LiveCatalog.supplements("178直播"));assertFalse(LiveCatalog.supplements("JRKAN"));}

 @Test public void preparationRoomsSurvive88CatalogParsing()throws Exception{String html="<li class='list-group-item live-list-group-time'>2026-11-10</li><li class='list-group-item'><span class='game-type'>NBA</span><span class='team-name'>甲</span><span class='team-name'>乙</span><span class='category-game-time'>13:00</span><a href='/live/123/play'>未开始</a></li>";List<Feeds.Match> rows=MoreSources.parse88(html,"live");assertEquals(1,rows.size());assertEquals(LiveState.Phase.SOON,LiveState.phase(rows.get(0),rows,now));}
 @Test public void preparationRoomsSurviveRainCatalogParsing()throws Exception{JSONObject room=new JSONObject().put("scheduleId",1).put("categoryId",2).put("hostName","甲").put("guestName","乙").put("status",0).put("matchTime",now+3600000).put("anchors",new JSONArray().put(new JSONObject().put("anchor",new JSONObject().put("roomNum","55"))));List<Feeds.Match> rows=MoreSources.parseRain(new JSONObject().put("data",new JSONObject().put("matches",new JSONArray().put(room))),"live");assertEquals(1,rows.size());assertEquals(LiveState.Phase.SOON,LiveState.phase(rows.get(0),rows,now));}
}
